import { parseCsv } from '../src/csv.js';
import { formatSummary, summarise } from '../src/summarise.js';

const USAGE = 'usage: colsummary <file.csv> --column <name>';

function parseArgs(args) {
  let file;
  let column;
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--column') {
      column = args[i + 1];
      if (column === undefined) throw new Error('--column needs a name');
      i += 1;
    } else if (args[i].startsWith('--')) throw new Error(`unknown option ${args[i]}`);
    else if (file === undefined) file = args[i];
    else throw new Error(`unexpected argument ${args[i]}`);
  }
  if (file === undefined) throw new Error('no file named');
  if (column === undefined) throw new Error('no --column given');
  return { file, column };
}

async function main(args) {
  let options;
  try {
    options = parseArgs(args);
