import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const USAGE = 'usage: wordfreq <file> [--top N]';

// A word is a maximal run of letters, digits and apostrophes, compared and printed in lower case (R3).
export function tokenize(text) {
  return (text.match(/[\p{L}\p{N}']+/gu) ?? []).map((w) => w.toLowerCase());
}

// Each word with its count; a text with no word has none (R7).
export function count(words) {
  const counts = new Map();
  for (const w of words) counts.set(w, (counts.get(w) ?? 0) + 1);
  return counts;
}

// Most frequent first, equal counts in alphabetical order (R4), the first n (R1, R2).
export function rank(counts, n = 10) {
  return [...counts].sort(([a, x], [b, y]) => y - x || (a < b ? -1 : a > b ? 1 : 0)).slice(0, n);
}

// One line per word, as `<count> <word>` (R1).
export function format(ranked) {
  return ranked.map(([w, c]) => `${c} ${w}\n`).join('');
}

export function parseArgs(args) {
  let file;
  let top = 10;
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--top') {
      const n = args[i + 1];
      if (n === undefined || !/^[1-9]\d*$/.test(n)) throw new Error(`--top must be a positive integer, got ${n ?? 'nothing'}`);
      top = Number(n);
      i += 1;
    } else if (args[i].startsWith('-')) throw new Error(`unknown option ${args[i]}`);
    else if (file === undefined) file = args[i];
    else throw new Error(`a second file ${args[i]}`);
  }
  if (file === undefined) throw new Error('no file named');
  return { file, top };
}

// The exit code: 0, 2 when the file cannot be read (R5), 1 on a bad argument (R6); nothing on standard output on either.
export function main(args, io = process) {
  let options;
  try {
    options = parseArgs(args);
  } catch (e) {
    io.stderr.write(`wordfreq: ${e.message}\n${USAGE}\n`);
    return 1;
  }
  let text;
  try {
    text = readFileSync(options.file, 'utf8');
  } catch (e) {
    io.stderr.write(`wordfreq: cannot read ${options.file}: ${e.code === 'ENOENT' ? 'no such file or directory' : e.message}\n`);
    return 2;
  }
  io.stdout.write(format(rank(count(tokenize(text)), options.top)));
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));

import test from 'node:test';
import assert from 'node:assert/strict';
import { main } from '../../src/wordfreq.js';

const io = () => {
  const out = { stdout: '', stderr: '' };
  return { out, stdout: { write: (s) => (out.stdout += s) }, stderr: { write: (s) => (out.stderr += s) } };
};

test('a file that cannot be read exits 2 with a message on standard error (R5)', () => {
  const s = io();
  assert.equal(main(['no-such-file.txt'], s), 2);
  assert.equal(s.out.stdout, '');
  assert.match(s.out.stderr, /^wordfreq: cannot read no-such-file\.txt/);
});

test('no file exits 1 with the usage line (R6)', () => {
  const s = io();
  assert.equal(main([], s), 1);
  assert.equal(s.out.stdout, '');
  assert.match(s.out.stderr, /usage: wordfreq <file> \[--top N\]/);
});

test('--top 0 exits 1 (R6)', () => {
  assert.equal(main(['a.txt', '--top', '0'], io()), 1);
});

test('--top with no number exits 1 (R6)', () => {
  assert.equal(main(['a.txt', '--top'], io()), 1);
});

test('an option other than --top exits 1 (R6)', () => {
  assert.equal(main(['a.txt', '--json'], io()), 1);
});

