import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { count, main, rank, tokenize } from '../../src/wordfreq.js';

const counts = count(tokenize('b a c a b a d e f g h i j k l'));

test('ranks words by count, most frequent first (R1)', () => {
  assert.deepEqual(rank(counts).slice(0, 2), [['a', 3], ['b', 2]]);
});

test('prints the N most frequent words of a UTF-8 file, one per line as `<count> <word>` (R1, R2)', () => {
  const file = join(mkdtempSync(join(tmpdir(), 'wordfreq-')), 'words.txt');
  writeFileSync(file, 'Été: a b, été. A été!\n');
  let printed = '';
  const code = main([file, '--top', '2'], { stdout: { write: (s) => (printed += s) }, stderr: { write: () => {} } });
  assert.equal(code, 0);
  assert.equal(printed, '3 été\n2 a\n');
});

test('--top N keeps the N most frequent (R2)', () => {
  assert.equal(rank(counts, 3).length, 3);
});

